'use client'
import { useState, useEffect, useRef, useCallback } from 'react'
import dynamic from 'next/dynamic'

const ThreeExplosion = dynamic(() => import('./ThreeExplosion'), { ssr: false })
const RopeFooter = dynamic(() => import('./RopeFooter'), { ssr: false })

const RELEASE_DATE = new Date('2026-11-19T00:00:00')
const TRAILER_URL = 'https://www.youtube.com/watch?v=VQRLujxTm3c'
const SITE_URL = 'https://gta6out.it'
const EASTER_EGG_TEXT = 'You discovered the real GTA VI'

function getTimeLeft() {
  const now = new Date()
  const diff = RELEASE_DATE.getTime() - now.getTime()
  if (diff <= 0) return { days: 0, hours: 0, minutes: 0, seconds: 0, done: true }
  return {
    days: Math.floor(diff / (1000 * 60 * 60 * 24)),
    hours: Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
    minutes: Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60)),
    seconds: Math.floor((diff % (1000 * 60)) / 1000),
    done: false,
  }
}

function getAutoHype() {
  const remaining = RELEASE_DATE.getTime() - Date.now()
  const oneYear = 365 * 24 * 60 * 60 * 1000
  return Math.min(100, Math.max(0, (remaining / oneYear) * 100))
}

function useTypewriter(text: string, active: boolean, speed = 55) {
  const [displayed, setDisplayed] = useState('')
  useEffect(() => {
    if (!active) { setDisplayed(''); return }
    setDisplayed('')
    let i = 0
    const timer = setInterval(() => {
      i++
      setDisplayed(text.slice(0, i))
      if (i >= text.length) clearInterval(timer)
    }, speed)
    return () => clearInterval(timer)
  }, [active, text, speed])
  return displayed
}

function CountdownUnit({ value, label }: { value: number; label: string }) {
  return (
    <div className="countdown-unit">
      <div className="countdown-number">{String(value).padStart(2, '0')}</div>
      <div className="countdown-label">{label}</div>
    </div>
  )
}

function Fireworks() {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    canvas.width = window.innerWidth
    canvas.height = window.innerHeight
    const colors = ['#ff00cc', '#cc00ff', '#ff50aa', '#ffffff', '#aa00ff', '#ff8c00', '#ffcc00', '#ff4500']
    const particles: { x: number; y: number; vx: number; vy: number; alpha: number; color: string; size: number }[] = []
    function spawnBurst(x: number, y: number) {
      for (let i = 0; i < 90; i++) {
        const angle = (Math.PI * 2 * i) / 90
        const speed = 3 + Math.random() * 9
        particles.push({ x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed, alpha: 1, color: colors[Math.floor(Math.random() * colors.length)], size: 2 + Math.random() * 4 })
      }
    }
    let frame = 0
    let animId: number
    function animate() {
      ctx!.clearRect(0, 0, canvas!.width, canvas!.height)
      if (frame % 38 === 0) spawnBurst(100 + Math.random() * (canvas!.width - 200), 50 + Math.random() * (canvas!.height / 2))
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i]
        p.x += p.vx; p.y += p.vy; p.vy += 0.15; p.alpha -= 0.012
        if (p.alpha <= 0) { particles.splice(i, 1); continue }
        ctx!.save(); ctx!.globalAlpha = p.alpha; ctx!.fillStyle = p.color
        ctx!.shadowBlur = 10; ctx!.shadowColor = p.color
        ctx!.beginPath(); ctx!.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx!.fill(); ctx!.restore()
      }
      frame++
      animId = requestAnimationFrame(animate)
    }
    spawnBurst(canvas.width / 2, canvas.height / 3)
    animate()
    const onResize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight }
    window.addEventListener('resize', onResize)
    return () => { cancelAnimationFrame(animId); window.removeEventListener('resize', onResize) }
  }, [])
  return <canvas ref={canvasRef} className="fireworks-canvas" />
}

function CelebrationScreen() {
  return (
    <div className="released-wrapper">
      <Fireworks />
      <div className="released-content">
        <div className="released-label">IT&apos;S HERE</div>
        <img src="/media/gta6-logo.svg" alt="Grand Theft Auto VI" className="gta-logo released-logo" />
        <div className="released-title">GTA 6 IS OUT NOW!</div>
        <p className="released-sub">The wait is finally over. Vice City awaits.</p>
        <a href={TRAILER_URL} target="_blank" rel="noopener noreferrer" className="btn-trailer">
          ▶ WATCH THE TRAILER
        </a>
      </div>
      <footer className="footer">
        <div className="footer-line" />
        <p className="footer-text">Created by <span className="footer-author" style={{ cursor: 'default' }}>Rashica07</span></p>
        <div className="footer-line" />
      </footer>
    </div>
  )
}

function EasterEggModal({ isOpen, onClose }: { isOpen: boolean; onClose: () => void }) {
  const typed = useTypewriter(EASTER_EGG_TEXT, isOpen)
  const isDone = typed.length >= EASTER_EGG_TEXT.length

  if (!isOpen) return null
  return (
    <div className="egg-backdrop" onClick={onClose}>
      <div className="egg-modal" onClick={e => e.stopPropagation()}>
        <img src="/media/gta6-official.jpeg" alt="Official GTA VI Logo" className="egg-logo" />
        <p className="egg-typewriter">
          {typed}
          {!isDone && <span className="egg-cursor">|</span>}
        </p>
        <button className="egg-close" onClick={onClose}>CLOSE</button>
      </div>
    </div>
  )
}

const HOLD_DURATION = 3000

export default function HomeClient() {
  const [timeLeft, setTimeLeft] = useState(() => ({ days: 185, hours: 0, minutes: 0, seconds: 0, done: false }))
  const [glitch, setGlitch] = useState(false)
  const [shareFlash, setShareFlash] = useState(false)
  const [logoClicks, setLogoClicks] = useState(0)
  const [easterEggOpen, setEasterEggOpen] = useState(false)
  const [showExplosion, setShowExplosion] = useState(false)
  const [showCelebration, setShowCelebration] = useState(false)

  // Hype bar drag
  const trackRef = useRef<HTMLDivElement>(null)
  const [ballPos, setBallPos] = useState(50.8)
  const [isDragging, setIsDragging] = useState(false)
  const [isHolding, setIsHolding] = useState(false)
  const [holdProgress, setHoldProgress] = useState(0)
  const holdIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const holdStartRef = useRef<number>(0)
  const logoClickTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    setTimeLeft(getTimeLeft())
    setBallPos(getAutoHype())
    const interval = setInterval(() => setTimeLeft(getTimeLeft()), 1000)
    return () => clearInterval(interval)
  }, [])

  useEffect(() => {
    if (timeLeft.done) return
    const gi = setInterval(() => {
      setGlitch(true)
      setTimeout(() => setGlitch(false), 220)
    }, 4200)
    return () => clearInterval(gi)
  }, [timeLeft.done])

  const clearHold = useCallback(() => {
    if (holdIntervalRef.current) { clearInterval(holdIntervalRef.current); holdIntervalRef.current = null }
    setIsHolding(false)
    setHoldProgress(0)
  }, [])

  const startHold = useCallback(() => {
    if (holdIntervalRef.current) return
    holdStartRef.current = Date.now()
    setIsHolding(true)
    holdIntervalRef.current = setInterval(() => {
      const elapsed = Date.now() - holdStartRef.current
      const progress = Math.min(100, (elapsed / HOLD_DURATION) * 100)
      setHoldProgress(progress)
      if (progress >= 100) {
        clearInterval(holdIntervalRef.current!)
        holdIntervalRef.current = null
        setIsHolding(false)
        setHoldProgress(0)
        setShowExplosion(true)
      }
    }, 50)
  }, [])

  const updateBallPos = useCallback((clientX: number) => {
    if (!trackRef.current) return
    const rect = trackRef.current.getBoundingClientRect()
    const pos = Math.min(100, Math.max(0, ((clientX - rect.left) / rect.width) * 100))
    setBallPos(pos)
    if (pos >= 99) startHold()
    else clearHold()
  }, [startHold, clearHold])

  const handleTrackDown = useCallback((clientX: number) => {
    setIsDragging(true)
    updateBallPos(clientX)
  }, [updateBallPos])

  useEffect(() => {
    if (!isDragging) return
    const onMove = (e: MouseEvent) => updateBallPos(e.clientX)
    const onTouchMove = (e: TouchEvent) => updateBallPos(e.touches[0].clientX)
    const onEnd = () => { setIsDragging(false); clearHold() }
    window.addEventListener('mousemove', onMove)
    window.addEventListener('touchmove', onTouchMove)
    window.addEventListener('mouseup', onEnd)
    window.addEventListener('touchend', onEnd)
    return () => {
      window.removeEventListener('mousemove', onMove)
      window.removeEventListener('touchmove', onTouchMove)
      window.removeEventListener('mouseup', onEnd)
      window.removeEventListener('touchend', onEnd)
    }
  }, [isDragging, updateBallPos, clearHold])

  const handleLogoClick = useCallback(() => {
    setLogoClicks(prev => {
      const next = prev + 1
      if (next >= 5) {
        setEasterEggOpen(true)
        return 0
      }
      if (logoClickTimerRef.current) clearTimeout(logoClickTimerRef.current)
      logoClickTimerRef.current = setTimeout(() => setLogoClicks(0), 1800)
      return next
    })
  }, [])

  const handleShare = useCallback(() => {
    const text =
      `🚨 GTA 6 drops in ${timeLeft.days} days, ${timeLeft.hours} hours & ${timeLeft.minutes} minutes!\n` +
      `Vice City is almost here 🎮🔥\n\n` +
      `Track the countdown live 👉 ${SITE_URL}\n\n` +
      `#GTA6 #GrandTheftAutoVI #RockstarGames #ViceCity`
    window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}`, '_blank', 'noopener,noreferrer')
    setShareFlash(true)
    setTimeout(() => setShareFlash(false), 1000)
  }, [timeLeft.days, timeLeft.hours, timeLeft.minutes])

  if (showCelebration || timeLeft.done) return <CelebrationScreen />

  return (
    <div className="page-wrapper">
      {showExplosion && (
        <ThreeExplosion
          onComplete={() => {
            setShowExplosion(false)
            setShowCelebration(true)
          }}
        />
      )}

      <div className="bg-layer" />
      <div className="noise-overlay" />
      <div className="grid-overlay" />

      <EasterEggModal isOpen={easterEggOpen} onClose={() => setEasterEggOpen(false)} />

      <main className="content">
        {/* LOGO — click 5x for easter egg */}
        <div className="logo-section">
          <img
            src="/media/gta6-logo.svg"
            alt="Grand Theft Auto VI"
            className={`gta-logo${glitch ? ' glitch' : ''}`}
            onClick={handleLogoClick}
            draggable={false}
          />
        </div>

        {/* COUNTDOWN */}
        <div className="countdown-section">
          <p className="countdown-heading">RELEASING NOVEMBER 19, 2026</p>
          <div className="countdown-grid">
            <CountdownUnit value={timeLeft.days} label="DAYS" />
            <div className="countdown-sep">:</div>
            <CountdownUnit value={timeLeft.hours} label="HOURS" />
            <div className="countdown-sep">:</div>
            <CountdownUnit value={timeLeft.minutes} label="MINUTES" />
            <div className="countdown-sep">:</div>
            <CountdownUnit value={timeLeft.seconds} label="SECONDS" />
          </div>
        </div>

        {/* HYPE BAR */}
        <div className="hype-section">
          <div className="hype-header">
            <span className="hype-label">HYPE METER</span>
            <span className="hype-pct">{ballPos.toFixed(1)}%</span>
          </div>

          <div className="hype-track-wrapper">
            {/* Hold-progress lines around the bar */}
            {isHolding && (
              <>
                <div
                  className="hype-hold-line hype-hold-top"
                  style={{ width: `${holdProgress}%` }}
                />
                <div
                  className="hype-hold-line hype-hold-bottom"
                  style={{ width: `${holdProgress}%` }}
                />
              </>
            )}

            <div
              ref={trackRef}
              className="hype-track"
              onMouseDown={e => handleTrackDown(e.clientX)}
              onTouchStart={e => handleTrackDown(e.touches[0].clientX)}
            >
              <div className="hype-fill" style={{ width: `${ballPos}%` }} />
              <div
                className={`hype-ball${isDragging ? ' dragging' : ''}`}
                style={{ left: `${ballPos}%` }}
              />
            </div>
          </div>

          <div className="hype-ends">
            <span>LAUNCH DAY</span>
            <span>365 DAYS OUT</span>
          </div>
          <p className="hype-hint">
            {isHolding
              ? `HOLD... ${Math.round(holdProgress)}%`
              : 'DRAG THE BALL → HOLD AT 100% FOR 3s'}
          </p>
        </div>

        {/* BUTTONS */}
        <div className="buttons-row">
          <a href={TRAILER_URL} target="_blank" rel="noopener noreferrer" className="btn-trailer">
            ▶ WATCH THE TRAILER
          </a>
          <button className={`btn-share${shareFlash ? ' share-flash' : ''}`} onClick={handleShare}>
            𝕏 SHARE THE HYPE
          </button>
        </div>

        {/* TAGLINE */}
        <div className="tagline-section">
          <p className="tagline">
            <span className="tagline-accent">Welcome</span> to Vice City
          </p>
          <p className="tagline-sub">The wait is almost over. Get ready.</p>
        </div>
      </main>

      <footer className="footer">
        <div className="footer-line" />
        <p className="footer-text">
          Created by <RopeFooter />
        </p>
        <div className="footer-line" />
      </footer>
    </div>
  )
}
